import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.sc8Z_ZE3.js";const m=JSON.parse('{"title":"Limits today","description":"","frontmatter":{},"headers":[],"relativePath":"review-bot/limits.md","filePath":"review-bot/limits.md"}'),s={name:"review-bot/limits.md"};function n(r,e,l,h,c,d){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="limits-today" tabindex="-1">Limits today <a class="header-anchor" href="#limits-today" aria-label="Permalink to &quot;Limits today&quot;">​</a></h1><p>What the review bot does not do yet, or does differently from what you might expect. We fix these in the open; the <a href="https://octryx.ai/roadmap" target="_blank" rel="noreferrer">roadmap</a> has the order.</p><h2 id="hosts" tabindex="-1">Hosts <a class="header-anchor" href="#hosts" aria-label="Permalink to &quot;Hosts&quot;">​</a></h2><ul><li><strong>GitHub</strong> gets a commit status, not a check run with annotations. A check run needs a GitHub App, which Octryx AI does not ship yet.</li><li><strong>GitLab</strong> is tried on one self-hosted instance (GitLab CE 19), with webhook and sync. GitLab.com has not been tried. A failed status can block merges where &quot;Pipelines must succeed&quot; is on.</li><li><strong>Bitbucket</strong> shows suggestions as a plain code block, not a one-click suggestion. A command written in a finding&#39;s thread on Bitbucket Server or Data Center may not find its finding when it arrives through the webhook; the sync reads it correctly.</li><li><strong>Forks</strong> are not reviewed.</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><ul><li><strong>Protected branches</strong> apply to fix runs only.</li></ul><h2 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h2><ul><li>The <a href="/docs/review-bot/#scanners">scanners</a> run only on a review seat&#39;s device. Without one, the review has no scan, and the footer says so. A code-pattern scan (SAST) is planned, not part of the review yet.</li><li>If the reviewer gives no verdict, the status stays <strong>pending</strong> and the run waits for a person.</li><li>After a force push, the finding numbers start again at F1.</li><li>A webhook start that is waiting for a newer push is lost when the server restarts; the hourly sync picks the pull request up again.</li><li>The check that a suggestion only uses defined names covers Python only.</li></ul><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><ul><li><code>@octryx fix</code> and <code>@octryx write tests</code> need the <strong>PR fix</strong> workflow, which is off on a fresh installation until a platform admin switches it on.</li><li>Choosing the coding engine per command (<code>@octryx fix codex</code>) is not built yet.</li><li>On Bitbucket only Workspace admins and owners can use commands.</li></ul>',10)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
